void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize + Center + Fix aspect-ratio
    vec2 p = (fragCoord * 2. - iResolution.xy) / iResolution.y;

    vec2 p2 = p * 6.7 - sin(p * 6.7);
    float i = abs(sin(p2.x) * sin(p2.y) * 3.) + iTime * .3;

    // Uncomment this for an oblique background effect
    //i += (p.x - p.y) * .25;

    // Cosine palette
    vec3 color = cos(6.2831853 * (i + vec3(.25, .5, .75))) * .5 + .5;
    fragColor = vec4(color, 1.);
}
